insert into reporting.analysis_runs(
  product_id,methodology_version_id,run_type,status,input_hash,output_hash,
  started_at,completed_at,warnings,metadata
)
select p.id,m.id,'roi','completed','368ef6ab6071234ea376d0fb83060bd62bc50b7759727a502e4795253ec22704','abdb8a741efe654c9a7f7f38f2e2dbbfca2836bc6e60d1dd60aac7d7979b900c',
       '2026-07-23T12:00:00Z','2026-07-23T12:00:00Z',
       $warn$["Minimum Known Cost basis applies where mandatory ancillary costs are incomplete.","No universal course or pathway ranking is authorised by the v0.7 model.","Long-term lifetime superiority is not established by the five-year model horizon."]$warn$::jsonb,
       $meta${"workbook":"Nursing_ROI_Model_v0.7_Final_Control_Updated_Draft.xlsx","source_register":"Nursing_Source_Register_v0.7_Release_Gap_Closure.xlsx","pathways":3,"courses":7,"scenarios":9,"calculation_rows":189,"applicable_outputs":153,"not_applicable_outputs":36,"source_records":439,"verified_source_records":426,"approved_source_records":348,"model_frozen":true,"recalculation_required":false}$meta$::jsonb
from reporting.products p
join reporting.methodology_versions m
  on m.methodology_key='au-nursing-roi-model' and m.version='0.7'
where p.product_key='au-nursing-roi-focus-2026-v1'
  and not exists (
    select 1 from reporting.analysis_runs r
    where r.product_id=p.id and r.methodology_version_id=m.id
      and r.input_hash='368ef6ab6071234ea376d0fb83060bd62bc50b7759727a502e4795253ec22704' and r.output_hash='abdb8a741efe654c9a7f7f38f2e2dbbfca2836bc6e60d1dd60aac7d7979b900c'
  );

create temporary table _nursing_pathways(j jsonb) on commit drop;
insert into _nursing_pathways select value from jsonb_array_elements($p$[{"Pathway ID":"P-NUR-BRN","Pathway Name":"Bachelor of Nursing → Registered Nurse","Occupation":"Registered Nurse","Qualification Type":"Bachelor","Final Course Count":3,"Core Scenario Basis":"Verified course cost envelope","Course Duration Range":3,"Tuition Range":"AUD 130,500–133,800","Course Cities":"Brisbane; Melbourne; Adelaide","Income Benchmark":"NSW public-health RN Year 1 / Year 5 base","Result Status":"Draft Minimum Known Cost Result","Ranking Eligible?":"No","Decision IDs":"DEC-PD-01; CALC-EXC-ANC-RD-01","Key Limitation":"Ancillary costs incomplete"},{"Pathway ID":"P-NUR-DEN","Pathway Name":"Diploma of Nursing → Enrolled Nurse","Occupation":"Enrolled Nurse","Qualification Type":"Diploma","Final Course Count":2,"Core Scenario Basis":"TAFE NSW Randwick Results Draft fee scenarios","Course Duration Range":1.5,"Tuition Range":"AUD 28,500–29,360","Course Cities":"Sydney (Randwick)","Income Benchmark":"NSW public-health EN Year 1 / Year 5 base","Result Status":"Draft Minimum Known Cost Result","Ranking Eligible?":"No","Decision IDs":"DEC-PD-01; CALC-EXC-TAFE-FEE-RD-01; CALC-EXC-ANC-RD-01","Key Limitation":"TAFE NSW exact charge requires Offer or CoE; ancillary costs incomplete"},{"Pathway ID":"P-NUR-GRN","Pathway Name":"Graduate-entry Nursing → Registered Nurse","Occupation":"Registered Nurse","Qualification Type":"Master / graduate entry","Final Course Count":2,"Core Scenario Basis":"Verified UQ/UOW tuition envelope","Course Duration Range":2,"Tuition Range":"AUD 88,740–100,064","Course Cities":"Brisbane; Wollongong","Income Benchmark":"NSW public-health RN Year 1 / Year 5 base","Result Status":"Draft Minimum Known Cost Result","Ranking Eligible?":"No","Decision IDs":"DEC-PD-01; PM-GRN-LC-01; CALC-EXC-ANC-RD-01","Key Limitation":"Ancillary costs incomplete"}]$p$::jsonb);

insert into reporting.analysis_pathways(
  analysis_run_id,pathway_key,name,occupation,qualification_type,display_order,
  result_status,ranking_eligible,metadata
)
select (select r.id from reporting.analysis_runs r
join reporting.products p on p.id=r.product_id
join reporting.methodology_versions m on m.id=r.methodology_version_id
where p.product_key='au-nursing-roi-focus-2026-v1' and m.methodology_key='au-nursing-roi-model' and m.version='0.7'
  and r.input_hash='368ef6ab6071234ea376d0fb83060bd62bc50b7759727a502e4795253ec22704' and r.output_hash='abdb8a741efe654c9a7f7f38f2e2dbbfca2836bc6e60d1dd60aac7d7979b900c'
order by r.created_at desc limit 1),j->>'Pathway ID',j->>'Pathway Name',j->>'Occupation',
       j->>'Qualification Type',
       case j->>'Pathway ID' when 'P-NUR-BRN' then 1 when 'P-NUR-DEN' then 2 else 3 end,
       j->>'Result Status',
       coalesce(lower(j->>'Ranking Eligible?')='yes',false),
       j
from _nursing_pathways
on conflict (analysis_run_id,pathway_key) do update
set name=excluded.name,occupation=excluded.occupation,
    qualification_type=excluded.qualification_type,display_order=excluded.display_order,
    result_status=excluded.result_status,ranking_eligible=excluded.ranking_eligible,
    metadata=excluded.metadata;

create temporary table _nursing_scenarios(j jsonb) on commit drop;
insert into _nursing_scenarios select value from jsonb_array_elements($s$[{"scenario_key":"P-NUR-BRN:Conservative","pathway_key":"P-NUR-BRN","scenario_name":"Conservative","display_order":1,"metadata":{"pathway_display_order":1}},{"scenario_key":"P-NUR-BRN:Base","pathway_key":"P-NUR-BRN","scenario_name":"Base","display_order":2,"metadata":{"pathway_display_order":1}},{"scenario_key":"P-NUR-BRN:Optimistic","pathway_key":"P-NUR-BRN","scenario_name":"Optimistic","display_order":3,"metadata":{"pathway_display_order":1}},{"scenario_key":"P-NUR-DEN:Conservative","pathway_key":"P-NUR-DEN","scenario_name":"Conservative","display_order":1,"metadata":{"pathway_display_order":2}},{"scenario_key":"P-NUR-DEN:Base","pathway_key":"P-NUR-DEN","scenario_name":"Base","display_order":2,"metadata":{"pathway_display_order":2}},{"scenario_key":"P-NUR-DEN:Optimistic","pathway_key":"P-NUR-DEN","scenario_name":"Optimistic","display_order":3,"metadata":{"pathway_display_order":2}},{"scenario_key":"P-NUR-GRN:Conservative","pathway_key":"P-NUR-GRN","scenario_name":"Conservative","display_order":1,"metadata":{"pathway_display_order":3}},{"scenario_key":"P-NUR-GRN:Base","pathway_key":"P-NUR-GRN","scenario_name":"Base","display_order":2,"metadata":{"pathway_display_order":3}},{"scenario_key":"P-NUR-GRN:Optimistic","pathway_key":"P-NUR-GRN","scenario_name":"Optimistic","display_order":3,"metadata":{"pathway_display_order":3}}]$s$::jsonb);

insert into reporting.analysis_scenarios(
  analysis_run_id,pathway_id,scenario_key,scenario_name,display_order,status,metadata
)
select (select r.id from reporting.analysis_runs r
join reporting.products p on p.id=r.product_id
join reporting.methodology_versions m on m.id=r.methodology_version_id
where p.product_key='au-nursing-roi-focus-2026-v1' and m.methodology_key='au-nursing-roi-model' and m.version='0.7'
  and r.input_hash='368ef6ab6071234ea376d0fb83060bd62bc50b7759727a502e4795253ec22704' and r.output_hash='abdb8a741efe654c9a7f7f38f2e2dbbfca2836bc6e60d1dd60aac7d7979b900c'
order by r.created_at desc limit 1),ap.id,j->>'scenario_key',j->>'scenario_name',
       (j->>'display_order')::smallint,'controlled',j->'metadata'
from _nursing_scenarios
join reporting.analysis_pathways ap
  on ap.analysis_run_id=(select r.id from reporting.analysis_runs r
join reporting.products p on p.id=r.product_id
join reporting.methodology_versions m on m.id=r.methodology_version_id
where p.product_key='au-nursing-roi-focus-2026-v1' and m.methodology_key='au-nursing-roi-model' and m.version='0.7'
  and r.input_hash='368ef6ab6071234ea376d0fb83060bd62bc50b7759727a502e4795253ec22704' and r.output_hash='abdb8a741efe654c9a7f7f38f2e2dbbfca2836bc6e60d1dd60aac7d7979b900c'
order by r.created_at desc limit 1)
 and ap.pathway_key=j->>'pathway_key'
on conflict (analysis_run_id,scenario_key) do update
set pathway_id=excluded.pathway_id,scenario_name=excluded.scenario_name,
    display_order=excluded.display_order,status=excluded.status,metadata=excluded.metadata;

