insert into reporting.analysis_inputs(
  analysis_run_id,input_key,scope_type,scope_id,value,evidence_id
)
select (select r.id from reporting.analysis_runs r
join reporting.products p on p.id=r.product_id
join reporting.methodology_versions m on m.id=r.methodology_version_id
where p.product_key='au-nursing-roi-focus-2026-v1' and m.methodology_key='au-nursing-roi-model' and m.version='0.7'
  and r.input_hash='368ef6ab6071234ea376d0fb83060bd62bc50b7759727a502e4795253ec22704' and r.output_hash='abdb8a741efe654c9a7f7f38f2e2dbbfca2836bc6e60d1dd60aac7d7979b900c'
order by r.created_at desc limit 1),'course_sample:'||(j->>'Sample ID'),'programme',p.id::text,j,
       srr.metric_observation_id
from _nursing_samples
join catalog.programme_identifiers pi
  on pi.identifier_system='CRICOS_COURSE_CODE' and pi.identifier_value=j->>'CRICOS'
join catalog.programmes p on p.id=pi.programme_id
left join lateral (
  select sr.metric_observation_id
  from evidence.source_register_records sr
  where sr.record_id=(regexp_match(coalesce(j->>'Source Record IDs',''),'SR-NUR-[0-9]{4}'))[1]
) srr on true
on conflict (analysis_run_id,input_key,scope_type,scope_id) do update
set value=excluded.value,evidence_id=excluded.evidence_id;
